"use client";
import {useRef} from "react";
import { ElementReveal } from "@/components/application/animations/expanded/scroll/element-reveal";

// Install the component assets or replace these image URLs with your own.
const imageStyle = { width: "100%", height: "100%", objectFit: "cover", display: "block" } as const;
const photos = [
  [
    "/assets/zeus/hero_run_02.jpg",
    "Runner in motion"
  ],
  [
    "/assets/zeus/action_cyclist-climb_02.jpg",
    "Cyclist climbing a hill"
  ],
  [
    "/assets/zeus/action_leap_01.jpg",
    "Athlete in midair"
  ]
];
const items = photos.map(([src, alt], index) => ({ id: String(index), content: <img src={src} alt={alt} style={imageStyle} /> }));

export default function Example(){
 const scrollContainer=useRef<HTMLDivElement>(null);
 return <div ref={scrollContainer} tabIndex={0} role="region" aria-label="Scroll demonstration" style={{height:600,overflowY:"auto",overscrollBehavior:"contain",background:"#efefed",color:"#151515"}}>
  <div style={{height:"320%",position:"relative"}}>
   <div style={{position:"sticky",top:0,height:600,overflow:"hidden"}}>
        <ElementReveal
          scrollContainer={scrollContainer}
          scrub={0.12}
          trigger={"scroll"}
          effect={"slide"}
          direction={"up"}
          distance={70}
          stagger={0.35}
          rotation={18}
          blur={18}
          duration={1.2}
          style={{display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: "3%", padding: "18% 7%"}}
        >{items.map(item => <div key={item.id} style={{aspectRatio: .7, overflow: "hidden", borderRadius: 8}}>{item.content}</div>)}</ElementReveal>
   </div>
  </div>
 </div>;
}

