"use client";
import { Children, useRef, type ReactNode } from "react";
import {
  useScrollMotion,
  scrollUnits,
  type ScrollMotionProps,
  type ScrollEntranceOptions,
} from "./scroll-shared";
import { scrollEase, scrollStagger } from "./scroll-math";
export interface ElementRevealProps extends ScrollMotionProps, ScrollEntranceOptions {
  children: ReactNode;
  effect?: "fade" | "slide" | "scale" | "clip" | "blur" | "rotate";
  direction?: "up" | "down" | "left" | "right";
  distance?: number;
  stagger?: number;
  rotation?: number;
  blur?: number;
}
export function ElementReveal({
  children,
  effect = "slide",
  direction = "up",
  distance = 70,
  stagger = 0.35,
  rotation = 18,
  blur = 18,
  trigger = "enter",
  ...props
}: ElementRevealProps) {
  const root = useRef<HTMLDivElement>(null),
    items = Children.toArray(children);
  useScrollMotion(
    root,
    { ...props, trigger },
    ({ progress: p }) => {
      scrollUnits(root.current!).forEach((el, i) => {
        const q = scrollEase(scrollStagger(p, i, items.length, stagger)),
          axis = direction === "left" || direction === "right" ? "X" : "Y",
          sign = direction === "up" || direction === "left" ? 1 : -1;
        el.style.opacity = String(effect === "clip" ? 1 : q);
        el.style.transform =
          effect === "slide"
            ? `translate${axis}(${sign * distance * (1 - q)}px)`
            : effect === "scale"
              ? `scale(${0.65 + 0.35 * q})`
              : effect === "rotate"
                ? `perspective(700px) rotateX(${rotation * (1 - q)}deg) rotateZ(${rotation * 0.25 * (1 - q)}deg)`
                : "none";
        el.style.filter = effect === "blur" ? `blur(${blur * (1 - q)}px)` : "none";
        el.style.clipPath =
          effect === "clip"
            ? `inset(${direction === "down" ? (1 - q) * 100 : 0}% ${direction === "left" ? (1 - q) * 100 : 0}% ${direction === "up" ? (1 - q) * 100 : 0}% ${direction === "right" ? (1 - q) * 100 : 0}%)`
            : "none";
      });
    },
    `${items.length}:${effect}:${direction}:${distance}:${stagger}:${rotation}:${blur}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="element-reveal"
      className={props.className}
      style={props.style}
    >
      {items.map((item, i) => (
        <div
          data-scroll-unit={i}
          key={(typeof item === "object" && item !== null && "key" in item ? item.key : null) ?? i}
          style={{ transformOrigin: "50% 100%" }}
        >
          {item}
        </div>
      ))}
    </div>
  );
}
